/**
 * Member absences: one row per (org, member) recording when they are away and who covers for them.
 *
 * Every query is filtered by `orgId`. Time-window decisions ("is away now?") are made by the service, not here.
 */
import { and, eq } from "drizzle-orm";
import { getDb, memberAbsences } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toMemberAbsence } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

export interface AbsenceWrite {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly delegateUserId: UserId | null;
  readonly startsAt: IsoTimestamp;
  readonly endsAt: IsoTimestamp;
  readonly note: string | null;
  readonly stamp: IsoTimestamp;
}

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/** Replaces any existing absence for the member in this workspace. */
export async function upsertAbsence(input: AbsenceWrite): Promise<MemberAbsence> {
  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId: input.orgId,
      userId: input.userId,
      delegateUserId: input.delegateUserId,
      startsAt: input.startsAt,
      endsAt: input.endsAt,
      note: input.note,
      createdAt: input.stamp,
      updatedAt: input.stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: input.delegateUserId,
        startsAt: input.startsAt,
        endsAt: input.endsAt,
        note: input.note,
        updatedAt: input.stamp,
      },
    })
    .returning()
    .get();

  return toMemberAbsence(row);
}

export async function deleteAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/** Drops `delegateUserId` from every absence that names this user, keeping the absences themselves. */
export async function clearDelegation(
  orgId: OrgId,
  delegateUserId: UserId,
  stamp: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null, updatedAt: stamp })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, delegateUserId),
      ),
    )
    .run();
}

