cat > tests/services/zz-scratch-absence.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import { PermissionDeniedError } from "@/lib/permissions";
import * as memberRepo from "@/server/repositories/member-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberService from "@/server/services/member-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import { toIsoTimestamp, type OrgId, type UserId, type IsoTimestamp } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import { ORG_B } from "../helpers/factories";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
const H = 3600_000;
const iso = (ms: number) => toIsoTimestamp(new Date(ms)) as IsoTimestamp;

describe("scratch absence", () => {
  it("set/get/clear and validation", async () => {
    const t = await createTenant("sc-basic", "growth");
    const now = Date.now();
    const a = await memberService.setAbsence(t.actors.member, {
      orgId: t.org.id, userId: t.userIds.member, delegateUserId: t.userIds.admin,
      startsAt: iso(now - H), endsAt: iso(now + H), note: "trip",
    });
    expect(a.delegateUserId).toBe(t.userIds.admin);
    expect(await memberService.getAbsence(t.actors.viewer, t.org.id, t.userIds.member)).not.toBeNull();
    // replace
    const b = await memberService.setAbsence(t.actors.member, {
      orgId: t.org.id, userId: t.userIds.member, delegateUserId: null,
      startsAt: iso(now + 10 * H), endsAt: iso(now + 11 * H), note: null,
    });
    expect(b.delegateUserId).toBeNull();
    expect(await memberService.getAbsence(t.actors.member, t.org.id, t.userIds.member)).toMatchObject({ startsAt: iso(now + 10 * H) });
    await expect(memberService.setAbsence(t.actors.member, {
      orgId: t.org.id, userId: t.userIds.member, delegateUserId: t.userIds.member,
      startsAt: iso(now), endsAt: iso(now + H), note: null,
    })).rejects.toThrow();
    await expect(memberService.setAbsence(t.actors.member, {
      orgId: t.org.id, userId: t.userIds.member, delegateUserId: null,
      startsAt: iso(now + H), endsAt: iso(now), note: null,
    })).rejects.toThrow();
    await expect(memberService.setAbsence(t.actors.member, {
      orgId: t.org.id, userId: t.userIds.admin, delegateUserId: null,
      startsAt: iso(now), endsAt: iso(now + H), note: null,
    })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(memberService.clearAbsence(t.actors.member, t.org.id, t.userIds.admin)).rejects.toBeInstanceOf(PermissionDeniedError);
    await memberService.clearAbsence(t.actors.owner, t.org.id, t.userIds.member);
    expect(await memberService.getAbsence(t.actors.member, t.org.id, t.userIds.member)).toBeNull();
    await memberService.clearAbsence(t.actors.owner, t.org.id, t.userIds.member); // no-op
    await expect(memberService.getAbsence(t.actors.member, ORG_B, t.userIds.member)).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("ended absence reads null; delegate must be active", async () => {
    const t = await createTenant("sc-ended", "growth");
    const now = Date.now();
    await memberService.setAbsence(t.actors.member, {
      orgId: t.org.id, userId: t.userIds.member, delegateUserId: null,
      startsAt: iso(now - 2 * H), endsAt: iso(now - H), note: null,
    });
    expect(await memberService.getAbsence(t.actors.member, t.org.id, t.userIds.member)).toBeNull();
    await expect(memberService.setAbsence(t.actors.member, {
      orgId: t.org.id, userId: t.userIds.member, delegateUserId: "01HZZZZZZZZZZZZZZZZZZZZZZZ" as UserId,
      startsAt: iso(now), endsAt: iso(now + H), note: null,
    })).rejects.toBeInstanceOf(NotFoundError);
  });

  it("redirects assignment, not self-take, no chaining; removal drops delegate", async () => {
    const t = await createTenant("sc-assign", "growth");
    const now = Date.now();
    // member away, delegate admin
    await memberService.setAbsence(t.actors.owner, {
      orgId: t.org.id, userId: t.userIds.member, delegateUserId: t.userIds.admin,
      startsAt: iso(now - H), endsAt: iso(now + H), note: null,
    });
    // admin away, delegate viewer (chain test)
    await memberService.setAbsence(t.actors.owner, {
      orgId: t.org.id, userId: t.userIds.admin, delegateUserId: t.userIds.viewer,
      startsAt: iso(now - H), endsAt: iso(now + H), note: null,
    });
    const seen: any[] = [];
    const off: Unsubscribe = subscribe("issue.assigned", (p) => { seen.push(p); });
    const issue = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { title: "Redirect me", assigneeId: t.userIds.member }));
    expect(issue.assigneeId).toBe(t.userIds.admin);
    const other = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { title: "Self take", assigneeId: null }));
    const moved = await issueService.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: other.id, assigneeId: t.userIds.member });
    expect(moved.assigneeId).toBe(t.userIds.admin);
    // self take by away member: not redirected
    const mine = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Mine alone", assigneeId: null }));
    const taken = await issueService.assignIssue(t.actors.member, { orgId: t.org.id, issueId: mine.id, assigneeId: t.userIds.member });
    expect(taken.assigneeId).toBe(t.userIds.member);
    // admin's own assignment to viewer (not away) -> fine
    off();
    expect(seen.map((p) => p.assigneeId)).toEqual([t.userIds.admin, t.userIds.admin, t.userIds.member]);
    // chained: admin is away and delegate viewer; assigning to admin via member chain? admin is delegate-target only through member; check direct admin assignment goes to viewer
    const direct = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { title: "Direct to admin", assigneeId: t.userIds.admin }));
    expect(direct.assigneeId).toBe(t.userIds.viewer);

    // removal of delegate admin drops delegation
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: (await memberRepo.findMember(t.org.id, t.userIds.admin))!.id });
    const after = await memberService.getAbsence(t.actors.owner, t.org.id, t.userIds.member);
    expect(after).not.toBeNull();
    expect(after?.delegateUserId).toBeNull();
    const again = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { title: "No delegate now", assigneeId: t.userIds.member }));
    expect(again.assigneeId).toBe(t.userIds.member);
  });

  it("overdue goes to delegate; mention alerts me and delegate once", async () => {
    const t = await createTenant("sc-notify", "growth");
    const now = Date.now();
    await memberService.setAbsence(t.actors.owner, {
      orgId: t.org.id, userId: t.userIds.member, delegateUserId: t.userIds.viewer,
      startsAt: iso(now - H), endsAt: iso(now + H), note: null,
    });
    const issue = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { title: "Late one", assigneeId: null, dueAt: iso(now - 2 * H) }));
    await issueRepo.setIssueAssignee(t.org.id, issue.id, t.userIds.member);
    await runOverdueIssueJob(new Date(now));
    const rows = await notificationService.listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.viewer, unreadOnly: false, kind: ["issue_overdue"], limit: 25, cursor: null });
    const memberRows = await notificationService.listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.member, unreadOnly: false, kind: ["issue_overdue"], limit: 25, cursor: null });
    expect(rows.items).toHaveLength(1);
    expect(memberRows.items).toHaveLength(0);

